-- Stage 11b (5 of 5): the old Outreach Engine findings brought across, then its tables archived
-- Tom's choices from the review page (https://claude.ai/artifact/DLucB792pjaV87MDs4ufcm), 23 Oct 2026:
-- everything as suggested, except the Formers listed in supabase/.local/11b/choices.txt.
-- Generated by supabase/.local/11b/make_fix.py.
--
-- From the old engine's prospects that match exactly one business here: 504 websites into the new
-- businesses.website field (only where it is empty); social links, ad sightings and Tom's old outreach
-- notes appended to businesses.notes under "From the old Outreach Engine (archived 24 Oct 2026):"
-- (896 lines on 345 businesses, skipping any already in the notes); 37 emails and phones the app
-- lacks added to the main contact (or the unnamed "Contact" record). The 138 prospects that match nothing
-- and the 75 ambiguous ones stay in the archive only.
-- Then the 11 oe_* tables move, unchanged, to a new schema "archive" that the app's roles can't read.
-- Nothing is deleted.
-- Every row it changes is copied to cc_phase0_backup (reason 'stage11b_old_engine_2026_10_24') first.
-- Undo: supabase/data-fixes/20261024_stage11b_5_old_engine_undo.sql
-- Run with psql -v ON_ERROR_STOP=1 after migration 20261024_001_stage11b. It refuses to run twice.

BEGIN;

DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM cc_phase0_backup WHERE reason = 'stage11b_old_engine_2026_10_24') THEN
    RAISE EXCEPTION 'stage11b_old_engine_2026_10_24 has already been applied';
  END IF;
END $$;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'businesses' AND column_name = 'website') THEN
    RAISE EXCEPTION 'apply migration 20261024_001_stage11b first';
  END IF;
END $$;

