-- every business still exists, is not merged away and has the name Tom saw
DO $$ DECLARE bad text; BEGIN
  SELECT string_agg(DISTINCT m.biz_name, ', ') INTO bad
  FROM (SELECT biz, biz_name FROM _web UNION SELECT biz, biz_name FROM _note UNION SELECT biz, biz_name FROM _det) m LEFT JOIN businesses b ON b.id = m.biz
  WHERE b.id IS NULL OR b.name IS DISTINCT FROM m.biz_name OR b.merged_into IS NOT NULL;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'changed since the review: %', bad; END IF;
END $$;

INSERT INTO cc_phase0_backup (table_name, row_id, before_row, reason)
SELECT 'businesses', b.id, to_jsonb(b), 'stage11b_old_engine_2026_10_24' FROM businesses b
WHERE b.id IN (SELECT biz FROM _web UNION SELECT biz FROM _note);

UPDATE businesses b SET website = w.url FROM _web w WHERE b.id = w.biz AND coalesce(btrim(b.website), '') = '';

-- notes: skip a line whose text is already there
DELETE FROM _note n USING businesses b
WHERE b.id = n.biz AND position(lower(regexp_replace(n.line, '^- (Old outreach note: )?', '')) IN lower(coalesce(b.notes, ''))) > 0;
UPDATE businesses b SET notes = coalesce(nullif(rtrim(b.notes), '') || E'\n\n', '')
  || 'From the old Outreach Engine (archived 24 Oct 2026):' || E'\n' || x.block
FROM (SELECT biz, string_agg(line, E'\n' ORDER BY n) AS block FROM _note GROUP BY biz) x
WHERE b.id = x.biz;

-- emails and phones: to the main contact, else the unnamed "Contact" record; only if no contact has them
CREATE TEMP TABLE _to ON COMMIT DROP AS
SELECT d.*, coalesce(v.main_contact_id,
  (SELECT k.id FROM contacts k WHERE k.business_id = d.biz AND k.is_active ORDER BY k.name_is_placeholder DESC, k.created_at LIMIT 1)) AS contact
FROM _det d JOIN v_businesses v ON v.id = d.biz;
DELETE FROM _to t WHERE t.contact IS NULL
  OR (t.kind = 'email' AND EXISTS (SELECT 1 FROM contacts k, jsonb_array_elements_text(coalesce(k.emails, '[]')) e
        WHERE k.business_id = t.biz AND lower(btrim(e)) = lower(btrim(t.val))))
  OR (t.kind = 'phone' AND EXISTS (SELECT 1 FROM contacts k, jsonb_array_elements_text(coalesce(k.phones, '[]')) p
        WHERE k.business_id = t.biz AND right(regexp_replace(p, '\D', '', 'g'), 10) = right(regexp_replace(t.val, '\D', '', 'g'), 10)));
INSERT INTO cc_phase0_backup (table_name, row_id, before_row, reason)
SELECT 'contacts', k.id, to_jsonb(k), 'stage11b_old_engine_2026_10_24' FROM contacts k WHERE k.id IN (SELECT contact FROM _to);
UPDATE contacts k SET
  emails = coalesce(k.emails, '[]'::jsonb) || coalesce((SELECT jsonb_agg(DISTINCT btrim(t.val)) FROM _to t WHERE t.contact = k.id AND t.kind = 'email'), '[]'::jsonb),
  phones = coalesce(k.phones, '[]'::jsonb) || coalesce((SELECT jsonb_agg(DISTINCT btrim(t.val)) FROM _to t WHERE t.contact = k.id AND t.kind = 'phone'), '[]'::jsonb)
WHERE k.id IN (SELECT contact FROM _to);

-- archive the old engine: same tables, same rows, out of the app's way
CREATE SCHEMA IF NOT EXISTS archive;
REVOKE ALL ON SCHEMA archive FROM PUBLIC, anon, authenticated;
GRANT USAGE ON SCHEMA archive TO service_role;
ALTER TABLE public.oe_actions SET SCHEMA archive;
ALTER TABLE public.oe_business_links SET SCHEMA archive;
ALTER TABLE public.oe_business_types SET SCHEMA archive;
ALTER TABLE public.oe_competitor_ads SET SCHEMA archive;
ALTER TABLE public.oe_conversion_stats SET SCHEMA archive;
ALTER TABLE public.oe_digital_profiles SET SCHEMA archive;
ALTER TABLE public.oe_discovery_runs SET SCHEMA archive;
ALTER TABLE public.oe_mastersheet_cache SET SCHEMA archive;
ALTER TABLE public.oe_outreach_events SET SCHEMA archive;
ALTER TABLE public.oe_pending_matches SET SCHEMA archive;
ALTER TABLE public.oe_prospects SET SCHEMA archive;
REVOKE ALL ON ALL TABLES IN SCHEMA archive FROM anon, authenticated;
COMMENT ON SCHEMA archive IS 'Stage 11b (24 Oct 2026): the old Outreach Engine tables (oe_*), kept unchanged. Nothing reads them.';

DO $$ DECLARE lost int; BEGIN
  SELECT count(*) INTO lost FROM businesses b JOIN cc_phase0_backup k ON k.row_id = b.id AND k.reason = 'stage11b_old_engine_2026_10_24' AND k.table_name = 'businesses'
  WHERE left(coalesce(b.notes, ''), length(rtrim(coalesce(k.before_row->>'notes', '')))) <> rtrim(coalesce(k.before_row->>'notes', ''));
  IF lost > 0 OR (SELECT count(*) FROM pg_tables WHERE schemaname = 'archive') <> 11
     OR EXISTS (SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename LIKE 'oe\_%') THEN
    RAISE EXCEPTION 'check failed: % notes altered, or the tables did not all move', lost;
  END IF;
  RAISE NOTICE 'stage 11b old engine: % websites, % note lines on % businesses, % emails/phones on % contacts, % tables archived',
    (SELECT count(*) FROM businesses b JOIN _web w ON w.biz = b.id AND b.website = w.url), (SELECT count(*) FROM _note),
    (SELECT count(DISTINCT biz) FROM _note), (SELECT count(*) FROM _to), (SELECT count(DISTINCT contact) FROM _to), 11;
END $$;

COMMIT;
